/**
 * Curated, deterministic psychology guidance for the zero-network mode.
 *
 * Every entry follows the same safety shape: validate without diagnosing,
 * explain one useful mechanism, offer a few low-risk actions, and end with a
 * reflective question. It deliberately avoids treatment protocols, diagnosis,
 * medication advice, recovered-memory claims, and guaranteed outcomes.
 */

type GuidedLanguage = "RU" | "KG" | "EN";
type LocalizedReply = Record<GuidedLanguage, string>;

const replies: Record<string, LocalizedReply> = {
  emotion_regulation: {
    RU: `Сильная эмоция может захватить всё внимание — это не делает вас «слишком чувствительным». Регуляция не означает подавить чувство; задача — заметить его и выбрать действие, которое не навредит вам. Попробуйте: 1) назвать эмоцию и её силу от 0 до 10; 2) заметить, где она ощущается в теле; 3) сделать паузу и несколько мягких выдохов; 4) спросить себя: «К чему меня тянет и какой более безопасный шаг возможен?» Если эмоции регулярно становятся неуправляемыми, полезна работа с психологом. Какая эмоция сейчас сильнее всего и что произошло прямо перед ней?`,
    KG: `Күчтүү сезим бүт көңүлдү ээлеп алышы мүмкүн — бул сизди «өтө сезимтал» кылбайт. Жөнгө салуу сезимди басуу эмес; аны байкап, өзүңүзгө зыян келтирбеген аракетти тандоо. 1) Сезимди атап, күчүн 0дөн 10го чейин баалаңыз. 2) Денеде кайсы жерде сезилип жатканын байкаңыз. 3) Тыным жасап, бир нече жумшак дем чыгарыңыз. 4) «Бул сезим мени эмнеге түртүп жатат, коопсузураак кадам кайсы?» деп сураңыз. Сезимдер көп учурда башкарылбай калса, психолог менен иштөө пайдалуу. Азыр кайсы сезим эң күчтүү жана анын алдында эмне болду?`,
    EN: `A strong emotion can take over your attention; that does not make you “too sensitive.” Regulation is not suppression—the aim is to notice the feeling and choose an action that will not harm you. Try: 1) name the emotion and rate it 0–10; 2) notice where it shows up in your body; 3) pause for a few gentle exhales; and 4) ask, “What is this feeling urging me to do, and what safer action is available?” If emotions often feel unmanageable, a psychologist can help. Which emotion is strongest right now, and what happened just before it?`,
  },
  burnout: {
    RU: `Похоже, вы долго расходовали больше сил, чем успевали восстанавливать. Выгорание обычно относят к хроническому стрессу именно в рабочем контексте; похожие симптомы также бывают при депрессии, тревоге, нарушениях сна и физических заболеваниях, поэтому по чату диагноз поставить нельзя. На этой неделе: 1) отделите обязательное от желательного; 2) сократите или перенесите одну нагрузку; 3) запланируйте реальное восстановление, а не только «ничего не делать с чувством вины»; 4) обсудите нагрузку с руководителем или врачом, если истощение стойкое. Что сейчас сильнее: усталость, отстранённость от работы или ощущение бессилия?`,
    KG: `Сиз көптөн бери калыбына келгенден көбүрөөк күч жумшап жүргөндөй сезилет. Күйүп кетүү көбүнчө жумуштагы узак стресс менен байланышат; ушуга окшош белгилер депрессияда, тынчсызданууда, уйку же ден соолук көйгөйлөрүндө да болот, ошондуктан чат аркылуу диагноз коюлбайт. Бул аптада: 1) милдеттүү ишти кошумча иштен бөлүңүз; 2) бир жүктү азайтыңыз же жылдырыңыз; 3) чыныгы эс алууну пландаңыз; 4) чарчоо басылбаса, жетекчи же дарыгер менен сүйлөшүңүз. Азыр көбүрөөк кайсынысы бар: чарчоо, жумуштан алыстоо же натыйжасыздык сезими?`,
    EN: `It sounds as though you have been spending energy faster than you can restore it. Burnout is generally used for chronic workplace stress; similar symptoms can also occur with depression, anxiety, sleep problems, or physical illness, so chat cannot diagnose the cause. This week: 1) separate essential work from optional work; 2) reduce or defer one demand; 3) schedule actual recovery rather than guilty inactivity; and 4) discuss workload with a manager or clinician if exhaustion persists. Which is strongest now: exhaustion, distance or cynicism about work, or feeling ineffective?`,
  },
  motivation: {
    RU: `Отсутствие мотивации не всегда означает лень. Часто старт тормозят слишком большой шаг, неясный смысл, страх ошибки или истощение. Выберите действие на 5 минут, сформулируйте его глаголом («открыть документ и написать три строки»), уберите одно отвлечение и решите заранее, когда остановитесь. Мотивация нередко появляется после начала, а не до него. Если неделями не радует почти ничего и заметно страдают сон, аппетит или обычная жизнь, стоит поговорить со специалистом. Какое дело вы откладываете и почему оно важно лично вам?`,
    KG: `Мотивациянын жоктугу дайыма жалкоолук эмес. Баштоого кадамдын өтө чоңдугу, маанинин бүдөмүктүгү, ката кетирүүдөн коркуу же чарчоо тоскоол болушу мүмкүн. 5 мүнөттүк аракет тандаңыз, аны этиш менен так жазыңыз («документти ачып, үч сап жазуу»), бир алаксытууну алып салыңыз жана качан токтой турганыңызды алдын ала чечиңиз. Мотивация көп учурда баштагандан кийин келет. Эгер бир нече жума эч нерсе кубантпай, уйку же күнүмдүк жашоо бузулса, адиске кайрылуу маанилүү. Кайсы ишти кийинкиге калтырып жатасыз жана ал сиз үчүн эмнеси менен маанилүү?`,
    EN: `Low motivation is not automatically laziness. Starting is often blocked by an oversized task, unclear meaning, fear of error, or exhaustion. Choose a five-minute action, phrase it as a verb (“open the document and write three lines”), remove one distraction, and decide in advance when to stop. Motivation often follows action rather than preceding it. If almost nothing feels rewarding for weeks and sleep, appetite, or daily life are affected, consider professional support. What task are you avoiding, and why does it matter to you personally?`,
  },
  focus: {
    RU: `Рассеянность часто усиливается, когда мозг держит слишком много открытых задач, тревожится или устал. Сделайте короткий «контейнер внимания»: 1) запишите все незавершённые дела вне головы; 2) выберите один конкретный результат на ближайшие 20 минут; 3) уберите уведомления и лишние вкладки; 4) после таймера сделайте короткую паузу и решите, продолжать ли. Не ругайте себя за отвлечение — спокойно возвращайте внимание. Если концентрация резко изменилась или долго мешает жизни, обсудите это с врачом или психологом. На чём именно вы хотите сосредоточиться ближайшие 20 минут?`,
    KG: `Көңүлдүн чачырашы мээде бүтпөгөн иштер көп болгондо, тынчсызданганда же чарчаганда күчөйт. Кыска «көңүл алкагын» түзүңүз: 1) бүтпөгөн иштерди кагазга чыгарыңыз; 2) кийинки 20 мүнөт үчүн бир так натыйжа тандаңыз; 3) билдирмелерди жана ашыкча терезелерди жабыңыз; 4) убакыт бүткөндө кыска тыныгып, улантууну чечиңиз. Алаксыганыңыз үчүн өзүңүздү урушпай, көңүлдү жай кайтарыңыз. Концентрация кескин өзгөрсө же көпкө жашоого тоскоол болсо, адис менен талкуулаңыз. Кийинки 20 мүнөттө эмнеге көңүл бургуңуз келет?`,
    EN: `Attention often scatters when the mind is holding too many open tasks, feeling anxious, or running on too little rest. Create a short focus container: 1) write unfinished tasks outside your head; 2) choose one concrete result for the next 20 minutes; 3) silence notifications and close extra tabs; and 4) pause when the timer ends and decide whether to continue. Do not punish distraction—gently return. If concentration changed suddenly or persistently disrupts life, discuss it with a clinician. What exactly would you like to focus on for the next 20 minutes?`,
  },
  decision_making: {
    RU: `Неопределённость может заставлять искать вариант без риска, но такого выбора часто не существует. Попробуйте: 1) сформулировать решение одним предложением; 2) выбрать три критерия, которые действительно важны; 3) отделить обратимое решение от труднообратимого; 4) установить срок и выбрать самый небольшой безопасный тест, если решение обратимо. Сравнивайте варианты по фактам, а не по обещанию «никогда не пожалеть». Если на вас давят или решение касается безопасности, дайте себе время и привлеките надёжного человека. Какое решение вы принимаете и что в нём самое труднообратимое?`,
    KG: `Белгисиздик таптакыр тобокелсиз вариантты издетет, бирок андай тандоо көп учурда жок. 1) Чечимди бир сүйлөм менен жазыңыз. 2) Чындап маанилүү үч критерий тандаңыз. 3) Кайра өзгөртүүгө боло турган чечимди кыйын өзгөрө турган чечимден бөлүңүз. 4) Мөөнөт коюп, мүмкүн болсо кичине коопсуз сыноо жасаңыз. «Эч качан өкүнбөйм» деген сезимге эмес, фактыларга таяныңыз. Сизге басым жасалып жатса же коопсуздук тууралуу болсо, убакыт алып, ишенимдүү адамды кошуңуз. Кайсы чечимди кабыл алып жатасыз жана анын кайсы бөлүгү кайра өзгөртүүгө эң кыйын?`,
    EN: `Uncertainty can make you search for a risk-free option, but such an option often does not exist. Try: 1) state the decision in one sentence; 2) choose three criteria that genuinely matter; 3) separate reversible from hard-to-reverse choices; and 4) set a deadline and run the smallest safe test when the choice is reversible. Compare evidence, not the promise that you will “never regret it.” If someone is pressuring you or safety is involved, slow down and involve a trusted person. What decision are you making, and which part is hardest to reverse?`,
  },
  cognitive_distortions: {
    RU: `Автоматическая мысль может звучать убедительно и всё же быть не полным фактом. «Всё или ничего», катастрофизация, чтение мыслей и обобщение — это названия привычных способов обработки информации, а не обвинение в неправильном мышлении. Возьмите одну мысль и спросите: 1) какой факт её поддерживает; 2) какой факт не помещается в неё; 3) что я сказал бы другу; 4) какая более точная, не обязательно позитивная формулировка возможна? Например: не «я всё провалил», а «эта часть не получилась, и я могу исправить следующий шаг». Какую конкретную мысль вы хотите проверить?`,
    KG: `Автоматтык ой абдан ишенимдүү сезилсе да, толук факт болбой калышы мүмкүн. «Баары же эч нерсе», катастрофалаштыруу, башка адамдын оюн окуу жана ашыкча жалпылоо — ойду иштетүүнүн көнүмүш жолдору; бул өзүңүздү күнөөлөө эмес. Бир ойду алып сураңыз: 1) аны кайсы факт колдойт; 2) кайсы факт ага батпайт; 3) досума эмне демекмин; 4) позитивдүү эмес, бирок такыраак кандай ой бар? Мисалы: «баарын буздум» эмес, «бул бөлүгү болгон жок, кийинки кадамды оңдой алам». Кайсы конкреттүү ойду текшергиңиз келет?`,
    EN: `An automatic thought can feel convincing without being the whole fact. All-or-nothing thinking, catastrophizing, mind reading, and overgeneralizing are labels for common information-processing habits—not accusations that you are thinking “wrong.” Take one thought and ask: 1) what evidence supports it; 2) what evidence does not fit; 3) what would I tell a friend; and 4) what is a more accurate, not necessarily positive, version? For example, replace “I ruined everything” with “This part went badly, and I can adjust the next step.” Which exact thought would you like to examine?`,
  },
  attachment: {
    RU: `Разговор о привязанности может помочь заметить привычный способ искать близость и безопасность, но стили привязанности — не неизменный диагноз и не ярлык для партнёра. Реакции зависят от отношений и ситуации. Вместо «я тревожный тип» попробуйте разобрать цикл: что стало сигналом угрозы, какая мысль возникла, что вы сделали и как ответил другой человек. Затем сформулируйте прямую просьбу: «Когда связь пропадает, я тревожусь; напиши, пожалуйста, когда сможешь вернуться к разговору». Какой повторяющийся момент в отношениях заставляет вас чувствовать небезопасность?`,
    KG: `Байлануу стили жакындыкты жана коопсуздукту кантип издей турганыбызды байкоого жардам берет, бирок ал өзгөрбөс диагноз же өнөктөшкө тагылчу энбелги эмес. Реакция мамилеге жана кырдаалга жараша өзгөрөт. «Мен тынчсыз типмин» дегендин ордуна циклди караңыз: коркунучтун белгиси эмне болду, кандай ой келди, сиз эмне кылдыңыз, башка адам кандай жооп берди? Анан түз өтүнүч айтыңыз: «Байланыш үзүлгөндө тынчсызданам; сүйлөшүүгө качан кайта аларыңды жазып койчу». Мамиледе кайсы кайталанган учур сизди коопсуз эмес сездирет?`,
    EN: `Attachment language can help identify how you seek closeness and safety, but attachment styles are not fixed diagnoses or labels to assign a partner. Responses vary by relationship and context. Instead of “I am an anxious type,” map the cycle: what signaled threat, what thought appeared, what you did, and how the other person responded. Then make a direct request: “When contact suddenly stops, I feel anxious; please tell me when you can return to the conversation.” What recurring relationship moment makes you feel least secure?`,
  },
  communication_conflict: {
    RU: `Повторяющийся конфликт часто поддерживает не только тема, но и сам цикл: критика — защита — усиление — отдаление. Если нет угроз или насилия, попробуйте: 1) сделать паузу до снижения накала; 2) описать наблюдаемый факт без «всегда» и «никогда»; 3) назвать своё чувство и потребность; 4) попросить об одном конкретном действии; 5) коротко повторить, что вы услышали в ответ. Цель — понять и договориться, а не выиграть. При запугивании безопасность важнее разговора. Как выглядит ваш цикл ссоры — что обычно запускает его и что происходит дальше?`,
    KG: `Кайталанган чырды тема гана эмес, цикл да кармап турат: сын — коргонуу — күчөтүү — алыстоо. Коркутуу же зомбулук жок болсо: 1) эмоция басылганча тыныгыңыз; 2) «ар дайым» жана «эч качан» дебей, байкалган фактыны айтыңыз; 3) сезимиңизди жана муктаждыгыңызды атаңыз; 4) бир конкреттүү аракетти өтүнүңүз; 5) жооптон эмнени укканыңызды кыскача кайталаңыз. Максат — жеңүү эмес, түшүнүү жана келишүү. Коркутууда коопсуздук сүйлөшүүдөн маанилүү. Силердин уруш циклиңер эмнеден башталып, андан кийин эмне болот?`,
    EN: `A recurring conflict is often maintained not only by the topic but by a cycle: criticism, defense, escalation, withdrawal. If there is no threat or violence: 1) pause until intensity drops; 2) describe an observable event without “always” or “never”; 3) name your feeling and need; 4) request one concrete action; and 5) briefly reflect what you heard. The goal is understanding and agreement, not winning. With intimidation, safety matters more than communication technique. What usually starts your conflict cycle, and what happens next?`,
  },
  jealousy_trust: {
    RU: `Ревность может указывать на страх потери, прошлую боль или реальные нарушения договорённостей — но сама по себе она не доказывает измену. Сначала отделите подтверждённые факты от предположений, затем успокойте импульс проверять или обвинять и обсудите конкретные правила: что для вас считается нарушением, какая прозрачность добровольно приемлема и как восстанавливается доверие. Тайный контроль телефона, угрозы и изоляция партнёра не создают безопасность. После реальной измены восстановление требует времени и действий обеих сторон. Сейчас у вас есть проверяемый факт или главным образом пугающая неопределённость?`,
    KG: `Кызганыч жоготуу коркунучун, мурунку ооруну же чыныгы келишим бузулушун көрсөтүшү мүмкүн, бирок өзү эле чыккынчылыкты далилдебейт. Ырасталган фактыларды божомолдон бөлүңүз, текшерүү же айыптоо импульсун бир аз токтотуңуз, анан так эрежелерди сүйлөшүңүз: эмнени бузуу деп эсептейсиз, кандай ачыктык эки тарапка тең ыктыярдуу, ишеним кандай аракеттер менен калыбына келет? Телефонду жашыруун текшерүү, коркутуу жана обочолонтуу коопсуздук жаратпайт. Азыр сизде текшерилген факт барбы же негизинен коркунучтуу белгисиздикпи?`,
    EN: `Jealousy can signal fear of loss, earlier hurt, or an actual broken agreement, but the feeling itself does not prove betrayal. Separate verified facts from assumptions, let the urge to check or accuse settle, and discuss concrete agreements: what counts as a breach, what transparency is mutually voluntary, and what actions would rebuild trust. Secret phone surveillance, threats, and isolation do not create safety. After a real betrayal, repair takes time and participation from both people. Do you have a verifiable fact right now, or mainly frightening uncertainty?`,
  },
  breakup: {
    RU: `После расставания мозг может одновременно искать человека и помнить, почему отношения закончились. Это похоже на утрату, и волны чувств не означают, что решение обязательно было ошибкой. На ближайшие дни полезно: договориться с собой о границе контакта, убрать постоянные цифровые триггеры, поддерживать сон и еду, выбрать одного человека для связи и планировать день небольшими блоками. Не нужно срочно «забыть» или начинать новые отношения. Если функционировать долго не получается или появляются мысли о смерти, нужна профессиональная помощь. Что сейчас больнее всего: потеря человека, привычного будущего или чувство отвержения?`,
    KG: `Ажырашкандан кийин мээ бир убакта адамды издеп да, мамиле эмне үчүн бүткөнүн эстеп да турат. Бул жоготууга окшош; сезим толкундары чечим сөзсүз ката болгонун билдирбейт. Жакынкы күндөрдө байланыштын чегин аныктаңыз, тынымсыз санарип эскертмелерди азайтыңыз, уйку менен тамакты кармаңыз, бир ишенимдүү адам менен байланышып, күндү кичине бөлүктөргө пландаңыз. Дароо «унутууга» же жаңы мамиле баштоого милдеттүү эмессиз. Узакка кадимки жашоо мүмкүн болбой же өлүм жөнүндө ойлор чыкса, адис керек. Азыр көбүрөөк эмнеси оор: адамдын кетиши, күтүлгөн келечектин жоголушу же четке кагылуу сезими?`,
    EN: `After a breakup, the mind may search for the person while also remembering why the relationship ended. This resembles grief, and waves of emotion do not prove the decision was wrong. For the next few days: set a contact boundary, reduce constant digital reminders, protect sleep and meals, choose one safe person to contact, and structure the day in small blocks. You do not have to “get over it” quickly or begin another relationship. If daily functioning remains severely impaired or thoughts of death appear, seek professional help. What hurts most now: losing the person, the imagined future, or feeling rejected?`,
  },
  parenting: {
    RU: `Трудное поведение ребёнка часто сообщает о перегрузке, нехватке навыка или потребности в контакте; это не означает, что границы не нужны. Сначала помогите снизить накал: спокойный голос, короткая фраза и физическая безопасность. Затем признайте чувство («ты злишься») и удержите ясную границу («бить нельзя»), предложив допустимый выбор. После ситуации вернитесь к контакту и обсудите, что можно сделать в следующий раз. Совет зависит от возраста и развития ребёнка; при риске вреда нужна очная профессиональная помощь. Сколько лет ребёнку и что происходит непосредственно перед сложным поведением?`,
    KG: `Баланын оор жүрүм-туруму көбүнчө ашыкча чыңалууну, жетишпеген көндүмдү же байланыш муктаждыгын билдирет; бул чек кереги жок деген эмес. Адегенде чыңалууну азайтыңыз: тынч үн, кыска сүйлөм жана физикалык коопсуздук. Анан сезимди таанып («ачууланып жатасың») так чекти кармаңыз («урууга болбойт») жана мүмкүн болгон тандоо бериңиз. Кийин байланышып, кийинки жолу эмне кылса болорун сүйлөшүңүз. Кеңеш баланын жашына жана өнүгүүсүнө жараша болот; зыян коркунучунда очно адис керек. Бала канча жашта жана оор жүрүм-турумдун алдында эмне болот?`,
    EN: `Difficult behavior often communicates overload, a missing skill, or a need for connection; that does not mean limits are unnecessary. First reduce intensity with a calm voice, few words, and physical safety. Then acknowledge the feeling (“you are angry”) while holding a clear limit (“hitting is not allowed”) and offering an acceptable choice. Reconnect afterward and discuss what could happen next time. Guidance depends on the child’s age and development; risk of harm needs in-person professional support. How old is the child, and what happens immediately before the difficult behavior?`,
  },
  inner_child: {
    RU: `«Внутренний ребёнок» — полезная метафора для ранних потребностей, чувств и усвоенных способов защиты, но не отдельная сущность и не доказанный способ точно восстановить прошлое. Безопасная рефлексия может выглядеть так: назвать ситуацию сегодня, заметить знакомое чувство, спросить, чего вам не хватило тогда, и выбрать заботливое действие сейчас — например, границу, отдых или поддержку. Не заставляйте себя заново переживать эпизоды и не считайте возникающие образы точной памятью. При сильных травматических реакциях лучше работать с травма-информированным специалистом. Какую сегодняшнюю ситуацию вы связываете с этой метафорой?`,
    KG: `«Ички бала» — эрте кездеги муктаждыктарды, сезимдерди жана коргонуу жолдорун түшүнүүгө жардам берген метафора; ал өзүнчө жандык эмес жана өткөндү так калыбына келтирүүчү далилденген ыкма эмес. Коопсуз рефлексия: бүгүнкү кырдаалды атаңыз, тааныш сезимди байкаңыз, анда эмнеге муктаж болгонуңузду сураңыз жана азыр камкор аракет тандаңыз — мисалы, чек, эс алуу же колдоо. Окуяны кайра баштан өткөрүүгө өзүңүздү мажбурлабаңыз жана пайда болгон образды так эс тутум деп кабыл албаңыз. Күчтүү травмалык реакцияда адис менен иштөө жакшы. Бүгүнкү кайсы кырдаалды ушул метафора менен байланыштырасыз?`,
    EN: `The “inner child” is a reflective metaphor for early needs, feelings, and learned protections—not a separate entity or a proven method for reconstructing the past accurately. A safer exercise is to name today’s situation, notice the familiar feeling, ask what was missing then, and choose a caring action now, such as a boundary, rest, or support. Do not force yourself to relive events or treat emerging images as certain memories. Strong trauma reactions are better addressed with a trauma-informed professional. What present-day situation are you connecting with this metaphor?`,
  },
  perfectionism: {
    RU: `Перфекционизм часто пытается защитить от критики или стыда, но поднимает порог начала и делает результат вечным «недостаточно». Определите заранее, что означает «достаточно хорошо» для этой задачи, разделите черновик и редактирование, ограничьте время и оцените результат по цели, а не по отсутствию ошибок. Маленькая безопасная неточность иногда помогает увидеть, что последствия переносимы. Самоценность не равна качеству одной работы. Какой минимальный результат действительно выполнит задачу сегодня?`,
    KG: `Перфекционизм сындан же уяттан коргоого аракет кылат, бирок баштоо босогосун көтөрүп, натыйжаны дайыма «жетишсиз» кылат. Бул иш үчүн «жетиштүү жакшы» деген эмне экенин алдын ала аныктаңыз, караламаны түзөтүүдөн бөлүңүз, убакытка чек коюңуз жана ишти катасыздыгы боюнча эмес, максаты боюнча баалаңыз. Кичине коопсуз так эместик кесепеттин көтөрүмдүү экенин көрсөтүшү мүмкүн. Өз баалуулугуңуз бир иштин сапатына барабар эмес. Бүгүн тапшырманы чындап бүтүрө турган минималдуу натыйжа кайсы?`,
    EN: `Perfectionism often tries to protect against criticism or shame, but it raises the threshold for starting and makes every result feel insufficient. Define “good enough” for this task in advance, separate drafting from editing, set a time limit, and judge the result by its purpose rather than the absence of errors. A small, safe imperfection can sometimes show that the consequences are tolerable. Your worth is not the quality of one performance. What minimum result would genuinely complete today’s task?`,
  },
  people_pleasing: {
    RU: `Постоянно быть удобным может быть способом сохранить связь или избежать конфликта; это не слабость, но цена со временем растёт. Перед ответом возьмите паузу: «Я проверю и отвечу позже». Затем спросите себя, есть ли у вас желание, ресурс и реальное согласие. Начните с небольшого отказа: «Я не смогу это взять» — без длинного оправдания. Чужое разочарование неприятно, но не всегда означает, что вы поступили плохо. Если отказ небезопасен из-за угроз, сначала нужен план безопасности. Кому вам труднее всего сказать «нет» и чего вы ожидаете в ответ?`,
    KG: `Дайыма ыңгайлуу болуу байланышты сактоонун же чырдан качуунун жолу болушу мүмкүн; бул алсыздык эмес, бирок убакыт өтүп баасы өсөт. Жооп берерден мурда: «Тактап, кийин жооп берем» деп тыныгыңыз. Анан каалооңуз, күчүңүз жана чыныгы макулдугуңуз барбы деп сураңыз. Кичине баш тартуудан баштаңыз: «Муну ала албайм» — узун актанбастан. Башканын капа болушу жагымсыз, бирок сиз туура эмес кылдыңыз дегенди билдирбейт. Баш тартуу коркутуудан улам кооптуу болсо, биринчи коопсуздук планы керек. Кимге «жок» деп айтуу эң кыйын жана андан кандай жооп күтөсүз?`,
    EN: `Being consistently accommodating can be a way to preserve connection or avoid conflict. It is not weakness, but the cost can grow. Before answering, pause: “I need to check; I’ll reply later.” Then ask whether you have the desire, capacity, and genuine consent. Start with a small refusal: “I can’t take that on,” without a long defense. Someone else’s disappointment is uncomfortable but does not automatically mean you did wrong. If saying no is unsafe because of threats, prioritize a safety plan. Who is hardest to say no to, and what response do you expect?`,
  },
  guilt_shame: {
    RU: `Вина обычно говорит «я сделал что-то не так», а стыд — «со мной что-то не так». Полезно разделить действие и личность: уточните факты и свою реальную ответственность, исправьте то, что возможно, извинитесь без требования немедленного прощения и выберите другое действие на будущее. Если ответственности нет, чувство может быть следствием чужого давления или старой привычки. Самонаказание не равно ответственности. Что именно произошло, за какую часть отвечаете вы, а какая часть не в вашей власти?`,
    KG: `Күнөө сезими көбүнчө «мен туура эмес иш кылдым» дейт, ал эми уят «мен өзүм туура эмесмин» дейт. Аракетти инсандыктан бөлүңүз: фактыларды жана чыныгы жоопкерчилигиңизди тактаңыз, мүмкүн болгонун оңдоңуз, дароо кечирүүнү талап кылбай кечирим сураңыз жана кийинкиге башка аракет тандаңыз. Жоопкерчилик жок болсо, сезим бирөөнүн басымынан же эски адаттан чыгышы мүмкүн. Өзүн жазалоо жоопкерчиликке барабар эмес. Эмне болду, кайсы бөлүгү сиздин жоопкерчилигиңизде, кайсысы сиздин көзөмөлдө эмес?`,
    EN: `Guilt usually says “I did something wrong,” while shame says “there is something wrong with me.” Separate behavior from identity: clarify the facts and your actual responsibility, repair what is possible, apologize without demanding immediate forgiveness, and choose a different future action. If you were not responsible, the feeling may reflect pressure from someone else or an old learned pattern. Self-punishment is not the same as accountability. What happened, which part is yours to own, and which part was outside your control?`,
  },
  fear_phobia: {
    RU: `Страх — защитная реакция, а избегание быстро приносит облегчение, поэтому может закреплять страх в долгосрочной перспективе. Сначала уточните: опасность реальна сейчас или это прогноз? Вернитесь к окружающей обстановке, назовите опоры и выберите только посильный безопасный шаг. При сильной фобии не нужно самостоятельно устраивать резкое «погружение» или терпеть панику; постепенный план лучше составлять с квалифицированным специалистом, особенно если страх ограничивает жизнь. Чего именно вы боитесь, как часто это возникает и чего страх не даёт вам делать?`,
    KG: `Коркуу — коргоочу реакция; качуу тез жеңилдеткендиктен, узак мөөнөттө коркууну бекемдеп коюшу мүмкүн. Адегенде тактаңыз: коркунуч азыр чын эле барбы же бул божомолбу? Айланага көңүл буруп, таянычтарды атаңыз жана көтөрө ала турган коопсуз кадамды гана тандаңыз. Күчтүү фобияда өзүңүздү кескин «салып көрүү» же паникага чыдоо керек эмес; акырын планды квалификациялуу адис менен түзүү жакшы. Так эмнеден коркосуз, бул канчалык көп болот жана коркуу эмнени кылууга жол бербей жатат?`,
    EN: `Fear is protective, and avoidance brings quick relief, so it can maintain fear over time. First ask: is danger present now, or is this a prediction? Orient to your surroundings, identify supports, and choose only a manageable, safe step. With a strong phobia, do not force yourself into sudden intensive exposure or endure overwhelming panic alone; a gradual plan is best developed with a qualified professional, especially when fear restricts daily life. What exactly do you fear, how often does it happen, and what does it prevent you from doing?`,
  },
  social_anxiety: {
    RU: `Социальная тревога часто направляет внимание внутрь: «как я выгляжу, заметили ли мою ошибку?» — и заставляет переоценивать чужую оценку. Перед ситуацией сформулируйте один реалистичный прогноз вместо катастрофы, во время разговора возвращайте внимание к словам собеседника, а после запишите не только неловкости, но и нейтральные факты. Выберите небольшой посильный шаг, а не требование сразу стать уверенным. Если избегание сильно сужает жизнь, помогает работа со специалистом. Какая конкретная социальная ситуация пугает и что, по вашему прогнозу, там произойдёт?`,
    KG: `Социалдык тынчсыздануу көңүлдү ичкери бурат: «кандай көрүнүп жатам, катамды байкаштыбы?» — жана башкалардын баасын ашыкча чоңойтот. Кырдаалдын алдында катастрофанын ордуна бир реалдуу божомол түзүңүз, сүйлөшүүдө көңүлдү маектештин сөзүнө кайтарыңыз, кийин ыңгайсыздыкты эле эмес, бейтарап фактыларды да жазыңыз. Дароо ишенимдүү болууну талап кылбай, кичине көтөрүмдүү кадам тандаңыз. Качуу жашоону катуу чектесе, адис жардам берет. Кайсы конкреттүү социалдык кырдаал коркутат жана ал жерде эмне болот деп күтөсүз?`,
    EN: `Social anxiety often turns attention inward—“How do I look? Did they notice that mistake?”—and overestimates other people’s judgment. Before the situation, make one realistic prediction rather than a catastrophe; during it, return attention to the other person’s words; afterward, record neutral facts as well as awkward moments. Choose one manageable step rather than demanding instant confidence. If avoidance significantly narrows your life, professional support can help. Which specific social situation scares you, and what do you predict will happen?`,
  },
  work_stress: {
    RU: `Рабочий стресс становится тяжелее, когда требования высоки, а контроля и восстановления мало. Разделите ситуацию на три части: что вы контролируете сегодня, о чём можете договориться и что находится вне вашей власти. Уточните приоритеты письменно, обозначьте реалистичный объём, добавьте короткие паузы и границу окончания рабочего времени. Если есть травля, дискриминация или небезопасные условия, фиксируйте факты и ищите подходящий внутренний или внешний канал поддержки — это не просто вопрос «устойчивости». Какой один фактор сейчас создаёт больше всего давления: объём, неопределённость, отношения или отсутствие контроля?`,
    KG: `Жумуштагы стресс талап жогору, көзөмөл жана калыбына келүү аз болгондо оорлойт. Кырдаалды үчкө бөлүңүз: бүгүн эмнени көзөмөлдөйсүз, эмнени сүйлөшүп өзгөртүүгө болот, эмне сиздин бийликте эмес. Артыкчылыктарды жазуу түрүндө тактаңыз, реалдуу көлөмдү белгилеңиз, кыска тыныгуу жана иш убактысынын бүтүү чегин коюңуз. Куугунтук, басмырлоо же кооптуу шарт болсо, фактыларды каттап, ички же тышкы колдоо издеңиз — бул жөн гана «чыдамкайлык» маселеси эмес. Азыр эң чоң басым эмнеден: көлөм, белгисиздик, мамиле же көзөмөлдүн жоктугу?`,
    EN: `Work stress grows when demands are high and control or recovery is low. Divide the situation into what you control today, what can be negotiated, and what is outside your control. Clarify priorities in writing, state a realistic workload, add brief recovery pauses, and set an end-of-work boundary. If bullying, discrimination, or unsafe conditions are present, document facts and seek an appropriate internal or external support channel—this is not merely a resilience problem. Which factor creates the most pressure now: volume, uncertainty, relationships, or lack of control?`,
  },
  study_exams: {
    RU: `Экзаменационная тревога может создавать ощущение, что нужно учиться всё время, хотя перегрузка ухудшает запоминание. Составьте список тем, выберите самое важное, учитесь короткими блоками с активным воспроизведением без подсказки, а не только перечитыванием, и заранее потренируйте формат задания. Сон и перерывы — часть подготовки, а не потеря времени. Перед экзаменом вернитесь к одному вопросу за раз и мягкому выдоху. Если тревога приводит к частым паническим приступам или полному избеганию, стоит обратиться за поддержкой. Какой экзамен впереди и какая тема сейчас самая слабая?`,
    KG: `Экзамендик тынчсыздануу дайыма окуш керек деген сезим жаратат, бирок ашыкча жүк эстөөнү начарлатат. Темалардын тизмесин түзүп, эң маанилүүсүн тандаңыз, кыска блоктор менен жардамсыз эстеп айтып машыгыңыз жана тапшырманын форматын алдын ала сынаңыз. Уйку жана тыныгуу — даярдыктын бөлүгү, убакытты жоготуу эмес. Экзаменде бир учурда бир суроого жана жумшак дем чыгарууга кайтыңыз. Тынчсыздануу тез-тез паникага же толук качууга алып келсе, колдоо керек. Алдыңызда кайсы экзамен бар жана кайсы тема азыр эң алсыз?`,
    EN: `Exam anxiety can create pressure to study constantly, even though overload impairs learning. List the topics, prioritize the highest-value gaps, study in short blocks using active recall rather than rereading alone, and practice the task format in advance. Sleep and breaks are part of preparation, not wasted time. During the exam, return to one question at a time and a gentle exhale. If anxiety causes frequent panic or complete avoidance, consider professional or educational support. Which exam is coming up, and which topic is currently weakest?`,
  },
  self_compassion: {
    RU: `Самосострадание — не жалость к себе и не отказ от ответственности. Это способ отвечать на трудность так, чтобы сохранить силы для полезного действия. Попробуйте три шага: «Сейчас мне трудно» — признать факт; «Люди сталкиваются с подобным» — уменьшить изоляцию; «Что бы поддержало меня без вреда?» — выбрать доброжелательную фразу и конкретное действие. Говорите с собой так же точно и уважительно, как с близким человеком: без ложной похвалы, но и без унижения. В какой ситуации внутренний критик сейчас звучит громче всего?`,
    KG: `Өзүнө боорукердик — өзүн аяп коюу же жоопкерчиликтен баш тартуу эмес. Бул кыйындыкка пайдалуу аракетке күч калтыра тургандай жооп берүү. Үч кадам: «Азыр мага кыйын» — фактыны таануу; «Мындай нерсе башка адамдарда да болот» — жалгыздыкты азайтуу; «Мага зыян келтирбей эмне колдоо берет?» — жумшак сөз жана конкреттүү аракет тандоо. Өзүңүз менен жакын адамыңыздай так жана сыйлуу сүйлөшүңүз: жалган мактоосуз, кемсинтүүсүз. Кайсы кырдаалда ички сынчыңыз азыр эң катуу угулат?`,
    EN: `Self-compassion is not self-pity or avoiding responsibility. It is responding to difficulty in a way that preserves capacity for useful action. Try three steps: “This is hard right now”—acknowledge the fact; “Other people struggle too”—reduce isolation; and “What would support me without causing harm?”—choose one kind phrase and one concrete action. Speak to yourself as accurately and respectfully as you would to someone you care about, without false praise or humiliation. In which situation is your inner critic loudest right now?`,
  },
  assertiveness: {
    RU: `Ассертивность — это ясность с уважением к себе и другому, а не жёсткость. Полезный каркас: «Когда происходит [наблюдаемый факт], я чувствую [эмоция], потому что для меня важно [потребность]. Я прошу [конкретное действие]. Если это продолжится, я сделаю [доступная вам граница]». Граница описывает ваше действие, а не попытку управлять другим. Скажите коротко, выдержите паузу и при необходимости повторите без новых оправданий. При угрозах или насилии не тренируйте прямую конфронтацию без плана безопасности. Какую одну просьбу или границу вы хотите сформулировать?`,
    KG: `Ассертивдүүлүк — катуулук эмес, өзүңүздү жана башка адамды сыйлаган тактык. Каркас: «[Байкалган факт] болгондо, мен [сезим] сезем, анткени мага [муктаждык] маанилүү. Мен [конкреттүү аракетти] өтүнөм. Бул уланса, мен [өзүңүз кыла ала турган чек] кылам». Чек башка адамды башкарбайт, сиздин аракетиңизди сүрөттөйт. Кыска айтып, тыныгып, керек болсо жаңы актануусуз кайталаңыз. Коркутуу же зомбулукта коопсуздук планысыз түз тирешпеңиз. Кайсы бир өтүнүчтү же чекти азыр тактагыңыз келет?`,
    EN: `Assertiveness is clarity with respect for yourself and the other person, not aggression. A useful frame is: “When [observable event] happens, I feel [emotion] because [need] matters to me. I am asking for [specific action]. If it continues, I will [boundary action available to you].” A boundary describes your action, not control over someone else. Keep it brief, pause, and repeat without adding new defenses if needed. With threats or violence, do not practice direct confrontation without a safety plan. What single request or boundary would you like to phrase?`,
  },
  trauma_boundary: {
    RU: `После травмирующего события возможны навязчивые воспоминания, избегание, настороженность, онемение и проблемы со сном, но только квалифицированный специалист может определить, соответствует ли это ПТСР или другому состоянию. Сейчас безопаснее не заставлять себя подробно пересказывать событие. Оглянитесь, назовите дату и место, почувствуйте опору стоп и выберите контакт с надёжным человеком. Если симптомы держатся, нарушают жизнь или есть провалы в безопасности, обратитесь к травма-информированному психологу или врачу. При непосредственной опасности звоните 112. Что происходит сейчас: воспоминание, оцепенение, сильная настороженность или что-то другое?`,
    KG: `Травмалык окуядан кийин кайталанган эскерүү, качуу, дайыма сак болуу, сезимсиздик жана уйку көйгөйү болушу мүмкүн, бирок ПТСР же башка абал экенин квалификациялуу адис гана аныктайт. Азыр окуяны майда-чүйдөсүнө чейин кайра айтууга өзүңүздү мажбурлабаңыз. Айланага карап, күндү жана жерди атаңыз, буттун таянычын сезиңиз жана ишенимдүү адам менен байланышыңыз. Белгилер созулуп, жашоону бузса, травма боюнча маалыматы бар психолог же дарыгер керек. Түз коркунучта 112ге чалыңыз. Азыр эмне болуп жатат: эскерүү, катып калуу, катуу сактык же башка нерсеби?`,
    EN: `After trauma, people may experience intrusive memories, avoidance, hypervigilance, numbness, or sleep problems, but only a qualified professional can determine whether this meets criteria for PTSD or something else. Do not force yourself to recount the event in detail right now. Look around, name today’s date and location, feel your feet supported, and contact a trusted person. If symptoms persist, impair daily life, or create safety gaps, seek a trauma-informed psychologist or clinician. Call 112 for immediate danger. What is happening now: a memory, numbness, intense alertness, or something else?`,
  },
  addiction_boundary: {
    RU: `Проблемное употребление — не просто недостаток силы воли, и просить помощь не стыдно. Я не могу определить зависимость или составить схему отмены по переписке. Запишите вещество или поведение, частоту, количество, последствия и когда было последнее употребление; свяжитесь с врачом или профильной службой. Резко прекращать некоторые вещества, особенно алкоголь или седативные препараты после регулярного употребления, может быть опасно — нужен медицинский план. При судорогах, потере сознания, спутанности, тяжёлом дыхании или передозировке звоните 112. О каком веществе или поведении речь и есть ли сейчас признаки отмены?`,
    KG: `Көйгөйлүү колдонуу жөн гана эрктин аздыгы эмес, жардам суроо уят эмес. Мен чат аркылуу көз карандылыкты аныктай же токтотуу схемасын түзө албайм. Затты же жүрүм-турумду, канчалык көп жана канча колдонгонуңузду, кесепеттерин жана акыркы колдонууну жазыңыз; дарыгер же атайын кызмат менен байланышыңыз. Айрым заттарды, өзгөчө алкоголду же тынчтандыруучу дарыларды туруктуу колдонгондон кийин кескин токтотуу кооптуу болушу мүмкүн — медициналык план керек. Тырышуу, эс-учун жоготуу, башаламандык, дем жетпөө же ашыкча доза болсо 112ге чалыңыз. Кайсы зат же жүрүм-турум жөнүндө сөз болуп жатат жана азыр токтотуу белгилери барбы?`,
    EN: `Problematic use is not simply a lack of willpower, and asking for help is not shameful. I cannot diagnose addiction or design a withdrawal plan through chat. Record the substance or behavior, frequency, amount, consequences, and time of last use, then contact a clinician or specialist service. Abruptly stopping some substances—especially alcohol or sedatives after regular use—can be dangerous and needs a medical plan. Call 112 for seizures, loss of consciousness, severe confusion, major breathing difficulty, or suspected overdose. Which substance or behavior is involved, and are withdrawal symptoms happening now?`,
  },
  eating_body_image: {
    RU: `Тяжёлые отношения с едой или телом заслуживают помощи независимо от веса и внешнего вида. Я не буду предлагать диету, подсчёт калорий, очищение или способы скрыть симптомы. Полезный следующий шаг — рассказать врачу или специалисту по расстройствам пищевого поведения о правилах вокруг еды, перееданиях, ограничениях, рвоте/слабительных, чрезмерных тренировках и физических симптомах; можно взять близкого человека на приём. При обмороке, боли в груди, выраженной слабости, спутанности или невозможности удерживать жидкость нужна срочная медицинская помощь. Что беспокоит больше: ограничения, потеря контроля, компенсирующие действия или ненависть к телу?`,
    KG: `Тамак же дене менен оор мамиле салмакка жана көрүнүшкө карабай жардамга татыктуу. Мен диета, калория саноо, «тазалануу» же белгилерди жашыруу жолдорун сунуштабайм. Кийинки кадам — дарыгерге же тамактануу бузулушу боюнча адиске тамак эрежелери, ашыкча жеп коюу, чектөө, кусуу/ич алдырма, ашыкча машыгуу жана денедеги белгилер тууралуу айтуу; кабыл алууга жакын адамды кошсо болот. Эс ооп калуу, көкүрөк оорусу, катуу алсыздык, башаламандык же суюктукту кармай албоо болсо шашылыш жардам керек. Көбүрөөк эмнеси тынчсыздандырат: чектөө, көзөмөлдү жоготуу, компенсациялык аракет же денени жек көрүүбү?`,
    EN: `A difficult relationship with food or the body deserves help at any weight or appearance. I will not provide diets, calorie targets, purging advice, or ways to hide symptoms. A useful next step is to tell a clinician or eating-disorder specialist about food rules, bingeing, restriction, vomiting/laxatives, excessive exercise, and physical symptoms; bringing a trusted person may help. Fainting, chest pain, severe weakness, confusion, or inability to keep fluids down needs urgent medical care. What is most concerning now: restriction, loss of control, compensating behaviors, or intense body hatred?`,
  },
  therapist_selection: {
    RU: `Выбор психолога — это не только симпатия, но и квалификация, прозрачность и безопасность. Уточните образование и право практиковать, опыт с вашей темой, подход и его доказательную основу, конфиденциальность и исключения, стоимость/отмены и порядок действий в кризисе. На первых встречах оцените, слушает ли специалист, согласует ли цели и объясняет ли методы; вы вправе задавать вопросы и отказаться. Красные флаги — гарантии исцеления, давление отказаться от врача, нарушение границ, секретность методов или финансовая эксплуатация. Какую тему вы хотите принести в терапию и что для вас особенно важно в контакте со специалистом?`,
    KG: `Психолог тандоо жактыруу гана эмес, квалификация, ачыктык жана коопсуздук. Билимин жана иштөөгө укугун, сиздин тема боюнча тажрыйбасын, ыкмасын жана далилдик негизин, купуялуулукту жана анын чектерин, бааны/жокко чыгарууну, кризистеги тартипти сураңыз. Алгачкы жолугушууда адис угабы, максатты сиз менен макулдашабы жана ыкманы түшүндүрөбү — баалаңыз; суроо берүүгө жана баш тартууга укуктуусуз. Айыгууга кепилдик, дарыгерден баш тартууга басым, чек бузуу, ыкманы жашыруу же акча жагынан пайдалануу — кооптуу белги. Терапияга кайсы теманы алып баргыңыз келет жана адис менен байланышта сиз үчүн эмне маанилүү?`,
    EN: `Choosing a therapist involves more than liking them; consider qualifications, transparency, and safety. Ask about training and license or registration, experience with your concern, the approach and its evidence base, confidentiality and its limits, fees/cancellations, and crisis procedures. In early sessions, notice whether the therapist listens, agrees goals with you, and explains methods; you may ask questions or decline. Red flags include guaranteed cures, pressure to stop medical care, boundary violations, secret methods, or financial exploitation. What concern would you bring to therapy, and what matters most to you in the working relationship?`,
  },
  journaling_reflection: {
    RU: `Дневник может помогать замечать закономерности, если не превращается в бесконечное пережёвывание мыслей. Ограничьте практику 10–15 минутами и используйте четыре строки: «Что произошло — только наблюдаемые факты? Что я почувствовал и заметил в теле? Какая потребность или ценность затронута? Какой небольшой следующий шаг возможен?» В конце запишите одну вещь, которую вы не знаете наверняка. Если запись усиливает травматические воспоминания или вы теряете связь с настоящим, остановитесь и вернитесь к окружающей обстановке; это лучше обсуждать со специалистом. Какую ситуацию вы хотите осмыслить сегодня?`,
    KG: `Күндөлүк ойлорду чексиз айлантуу эмес, мыйзамченемди байкоого жардам берсе пайдалуу. Практиканы 10–15 мүнөт менен чектеп, төрт сап колдонуңуз: «Эмне болду — байкалган фактылар гана? Эмне сездим жана денеде эмнени байкадым? Кайсы муктаждык же баалуулук козголду? Кайсы кичине кийинки кадам мүмкүн?» Аягында так билбеген бир нерсени жазыңыз. Жазуу травмалык эскерүүнү күчөтсө же азыркы учур менен байланыш жоголсо, токтоп, айланага көңүл буруңуз; муну адис менен талкуулаган жакшы. Бүгүн кайсы кырдаалды түшүнгүңүз келет?`,
    EN: `Journaling can reveal patterns when it does not become endless rumination. Limit it to 10–15 minutes and use four lines: “What happened—observable facts only? What did I feel and notice in my body? Which need or value was affected? What small next step is available?” End by noting one thing you do not know for certain. If writing intensifies traumatic memories or you lose connection with the present, stop and orient to your surroundings; that material is better explored with a professional. Which situation would you like to reflect on today?`,
  },
  general_psychology: {
    RU: `Психология изучает поведение и психические процессы: мысли, эмоции, внимание, обучение, отношения и влияние среды. Удобная рабочая модель — не искать одну «скрытую причину», а смотреть на цикл: ситуация → интерпретация → эмоции и тело → действие → последствия. Каждый элемент влияет на другие, поэтому изменение возможно с разных точек — через мысль, навык, среду, поддержку или поведение. Это модель для понимания, а не способ читать чужие мысли или ставить диагноз. Какой конкретный психологический термин или ситуацию вы хотите разобрать простым языком?`,
    KG: `Психология жүрүм-турумду жана психикалык процесстерди — ойду, сезимди, көңүлдү, үйрөнүүнү, мамилени жана чөйрөнүн таасирин — изилдейт. Пайдалуу иш модели бир «жашыруун себепти» издебей, циклди кароо: кырдаал → түшүндүрмө → сезим жана дене → аракет → натыйжа. Ар бир бөлүк башкаларга таасир этет, ошондуктан өзгөрүү ой, көндүм, чөйрө, колдоо же жүрүм-турум аркылуу башталышы мүмкүн. Бул түшүнүү модели; башка адамдын оюн окуу же диагноз коюу ыкмасы эмес. Кайсы конкреттүү психологиялык терминди же кырдаалды жөнөкөй тилде талдагыңыз келет?`,
    EN: `Psychology studies behavior and mental processes, including thoughts, emotions, attention, learning, relationships, and environmental influence. A useful working model is to avoid searching for one hidden cause and instead map a cycle: situation → interpretation → emotion and body → action → consequence. Each part affects the others, so change can begin through thinking, skills, environment, support, or behavior. This is a framework for understanding, not a way to read minds or diagnose people. Which specific psychology term or situation would you like explained in plain language?`,
  },
};

const conceptReplies: Record<string, LocalizedReply> = {
  reinforcement: {
    RU: `Подкрепление — это последствие, после которого поведение становится вероятнее. «Положительное» означает, что что-то добавили, а «отрицательное» — что неприятное убрали; это не значит «хорошее» и «плохое». Например, похвала может усилить попытки ребёнка, а исчезновение тревоги после избегания — непреднамеренно усилить само избегание. Эффект определяют по тому, меняется ли поведение, а не по намерению. Какое поведение и какое последствие вы хотите разобрать?`,
    KG: `Бекемдөө — андан кийин жүрүм-турумдун кайталануу ыктымалдыгы өскөн натыйжа. «Оң» — бир нерсе кошулду, «терс» — жагымсыз нерсе алынды дегенди билдирет; бул «жакшы» же «жаман» эмес. Мисалы, мактоо баланын аракетин күчөтүшү мүмкүн, ал эми качуудан кийин тынчсыздануунун басылышы качууну байкабай бекемдейт. Ниетке эмес, жүрүм-турум чындап өзгөрдүбү — ошого каралат. Кайсы жүрүм-турумду жана анын натыйжасын талдагыңыз келет?`,
    EN: `Reinforcement is a consequence after which a behavior becomes more likely. “Positive” means something was added; “negative” means something unpleasant was removed—it does not mean good versus bad. Praise may reinforce a child’s effort, while relief after avoidance may unintentionally reinforce more avoidance. The effect is identified by whether behavior changes, not by the person’s intention. Which behavior and consequence would you like to map?`,
  },
  conditioning: {
    RU: `Обусловливание — это обучение связям. При классическом обусловливании один сигнал начинает вызывать реакцию, потому что многократно сочетался с другим событием; при оперантном поведение меняется из-за своих последствий. Эти механизмы помогают понимать привычки и страхи, но не объясняют человека целиком: важны мысли, отношения, биология и среда. Какую приобретённую реакцию или привычку вы хотите понять?`,
    KG: `Шарттануу — байланыштарды үйрөнүү. Классикалык шарттанууда бир белги башка окуя менен көп коштолгондуктан реакция жарата баштайт; операнттык шарттанууда жүрүм-турум анын натыйжаларына жараша өзгөрөт. Бул механизмдер адат менен коркууну түшүндүрүүгө жардам берет, бирок адамды толук түшүндүрбөйт: ой, мамиле, биология жана чөйрө да маанилүү. Кайсы үйрөнүлгөн реакцияны же адатты түшүнгүңүз келет?`,
    EN: `Conditioning is learning associations. In classical conditioning, one cue begins to evoke a response after being paired with another event; in operant conditioning, behavior changes because of its consequences. These mechanisms help explain habits and fears, but they do not explain a whole person—thoughts, relationships, biology, and context also matter. Which learned reaction or habit would you like to understand?`,
  },
  unconscious: {
    RU: `В психологии «бессознательное» — широкое слово для процессов вне текущего осознания: автоматических ассоциаций, навыков, привычек и части эмоциональной обработки. Разные школы вкладывают в термин разный смысл. Это не скрытый голос, который всегда знает истину, и не основание считать любой образ точным воспоминанием. Полезнее проверять гипотезу по наблюдаемым повторяющимся ситуациям. Какой автоматический паттерн вы называете «подсознанием»?`,
    KG: `Психологияда «аң-сезимсиз» деген учурда аңдалбаган процесстерди — автоматтык байланыштарды, көндүмдөрдү, адаттарды жана сезимди иштетүүнүн бир бөлүгүн — билдирген кең термин. Ар башка мектептер аны ар башкача түшүндүрөт. Бул дайыма чындыкты билген жашыруун үн эмес жана ар бир образды так эс тутум деп эсептөөгө негиз бербейт. Гипотезаны кайталанган байкалчу кырдаалдар менен текшерген пайдалуу. Кайсы автоматтык үлгүнү «подсознание» деп атап жатасыз?`,
    EN: `In psychology, “the unconscious” is a broad term for processes outside current awareness, such as automatic associations, skills, habits, and some emotional processing. Different schools use the term differently. It is not a hidden voice that always knows the truth, and an image is not automatically an accurate memory. It is more useful to test a hypothesis against observable recurring situations. Which automatic pattern are you calling “subconscious”?`,
  },
  defense: {
    RU: `Психологические защиты — название для способов уменьшить внутреннее напряжение, иногда без полного осознания: например, отрицание, рационализация или перенос чувств на более безопасную цель. Защита не делает человека плохим и может временно помогать, но становится проблемой, если искажает факты или мешает действовать. По одному эпизоду нельзя надёжно «разоблачить» защиту другого человека. Какой повторяющийся эпизод вы пытаетесь понять?`,
    KG: `Психологиялык коргонуу — ички чыңалууну азайтуучу, кээде толук аңдалбаган жолдордун аталышы: мисалы, четке кагуу, рационалдаштыруу же сезимди коопсузураак нерсеге буруу. Коргонуу адамды жаман кылбайт жана убактылуу жардам берет, бирок фактыларды бурмалап же аракетке тоскоол болсо көйгөйгө айланат. Бир эле окуя боюнча башка адамдын коргонуусун так аныктоо мүмкүн эмес. Кайсы кайталанган окуяны түшүнүүгө аракет кылып жатасыз?`,
    EN: `Defense mechanisms are ways of reducing inner tension, sometimes outside full awareness—for example denial, rationalization, or redirecting feelings toward a safer target. A defense does not make someone bad and may help temporarily, but it becomes costly when it distorts facts or blocks action. One event is not enough to reliably “expose” another person’s defense. Which recurring situation are you trying to understand?`,
  },
  projection: {
    RU: `Проекцией называют гипотезу о том, что человек приписывает другому собственные трудные чувства или импульсы. Это понятие может быть полезно для саморефлексии, но им часто злоупотребляют, будто можно точно знать чужой внутренний мир. Вместо ярлыка разделите: что человек реально сказал или сделал, что вы предполагаете и что чувствуете сами. Какой наблюдаемый факт заставил вас подумать о проекции?`,
    KG: `Проекция деп адам өзүнүн көтөрүү кыйын болгон сезимин же түрткүсүн башка адамга таандык кылат деген гипотезаны айтышат. Бул өзүн талдоого пайдалуу болушу мүмкүн, бирок башка адамдын ички дүйнөсүн так билгендей колдонуу жаңылыш. Энбелгинин ордуна бөлүңүз: адам чындап эмне айтты же кылды, сиз эмнени болжоп жатасыз, өзүңүз эмне сездиңиз? Кайсы байкалган факт проекция жөнүндө ойлонтту?`,
    EN: `Projection is a hypothesis that someone is attributing their own difficult feelings or impulses to another person. It can support self-reflection, but it is often misused as though we can know someone else’s inner world with certainty. Instead of applying a label, separate what the person actually said or did, what you infer, and what you feel yourself. Which observable fact led you to think about projection?`,
  },
  empathy: {
    RU: `Эмпатия — способность замечать и пытаться понять переживание другого, не обязательно соглашаясь с ним и не принимая на себя ответственность всё исправить. Полезный ответ обычно включает внимание, проверку понимания и границу: «Похоже, тебе сейчас тяжело; я правильно понял? Я могу послушать десять минут». Эмпатия без границ может превращаться в истощение. В какой ситуации вам трудно одновременно понимать другого и сохранять себя?`,
    KG: `Эмпатия — башка адамдын тажрыйбасын байкап, түшүнүүгө аракет кылуу; бул сөзсүз макул болуу же баарын оңдоо жоопкерчилигин алуу эмес. Пайдалуу жоопто көңүл, түшүнүүнү текшерүү жана чек бар: «Азыр сага кыйын окшойт; туура түшүндүмбү? Он мүнөт уга алам». Чексиз эмпатия чарчоого айланышы мүмкүн. Кайсы кырдаалда башка адамды түшүнүп, ошол эле учурда өзүңүздү сактоо кыйын?`,
    EN: `Empathy is noticing and trying to understand another person’s experience without necessarily agreeing or taking responsibility to fix everything. A useful response combines attention, a check, and a boundary: “It sounds hard right now—did I understand? I can listen for ten minutes.” Empathy without boundaries can become exhausting. In which situation is it hard to understand the other person while also preserving yourself?`,
  },
  temperament: {
    RU: `Темперамент описывает относительно устойчивые особенности реактивности и саморегуляции — например, насколько быстро человек возбуждается, успокаивается или ищет новое. Это не судьба, не диагноз и не строгий «тип личности»: поведение меняют опыт, навыки, отношения и ситуация. Полезно спрашивать не «какой я тип?», а «в каких условиях эта особенность помогает, а где мне нужен другой навык?» Какую свою устойчивую реакцию вы хотите лучше понять?`,
    KG: `Темперамент реактивдүүлүк жана өзүн жөнгө салуунун салыштырмалуу туруктуу өзгөчөлүктөрүн сүрөттөйт — мисалы, адам канчалык тез козголуп, тынчтанып же жаңылыкты издейт. Бул тагдыр, диагноз же катуу «инсан тиби» эмес: жүрүм-турумду тажрыйба, көндүм, мамиле жана кырдаал өзгөртөт. «Мен кайсы типмин?» дегенден көрө «бул өзгөчөлүк кайда жардам берет, кайда башка көндүм керек?» деп суроо пайдалуу. Кайсы туруктуу реакцияңызды жакшыраак түшүнгүңүз келет?`,
    EN: `Temperament describes relatively stable differences in reactivity and self-regulation, such as how quickly someone becomes activated, settles, or seeks novelty. It is not destiny, a diagnosis, or a rigid personality “type”; experience, skills, relationships, and context all shape behavior. A more useful question than “What type am I?” is “Where does this tendency help, and where do I need another skill?” Which recurring reaction would you like to understand better?`,
  },
  resilience: {
    RU: `Психологическая устойчивость — не способность никогда не страдать и не обязанность терпеть вредные условия. Это процесс адаптации с опорой на навыки, отношения, доступные ресурсы и изменение самой среды. Начать можно с вопроса: что сейчас можно уменьшить, какую опору усилить и какой навык нужен для следующего шага? Если причина — насилие или системно небезопасная среда, задача не «стать сильнее», а повысить безопасность. Какая нагрузка сейчас проверяет вашу устойчивость?`,
    KG: `Психологиялык туруктуулук эч качан кыйналбоо же зыяндуу шартка чыдоо милдети эмес. Бул көндүм, мамиле, жеткиликтүү ресурс жана чөйрөнү өзгөртүү аркылуу ыңгайлашуу процесси. Баштоо үчүн: азыр эмнени азайтууга болот, кайсы таянычты күчөтүү керек, кийинки кадамга кайсы көндүм зарыл? Себеп зомбулук же дайыма кооптуу чөйрө болсо, максат «күчтүүрөөк болуу» эмес, коопсуздукту жогорулатуу. Азыр кайсы жүк сиздин туруктуулугуңузду сынап жатат?`,
    EN: `Psychological resilience is not never suffering or being obliged to tolerate harmful conditions. It is an adaptive process supported by skills, relationships, available resources, and changes to the environment itself. Start by asking what load can be reduced, which support can be strengthened, and which skill is needed for the next step. If the cause is abuse or a persistently unsafe environment, the task is not to become “tougher” but to increase safety. What current demand is testing your resilience?`,
  },
};

function psychologyConceptReply(input: string, language: GuidedLanguage) {
  const normalized = input.normalize("NFKC").toLocaleLowerCase("und");
  const concept =
    /подкреплен|бекемдөө|reinforcement/u.test(normalized)
      ? "reinforcement"
      : /обусловливан|шарттануу|conditioning/u.test(normalized)
        ? "conditioning"
        : /бессознательн|подсознани|аң-сезимсиз|unconscious|subconscious/u.test(
              normalized,
            )
          ? "unconscious"
          : /защитн.{0,8}механизм|коргонуу механизм|defen[cs]e mechanism/u.test(
                normalized,
              )
            ? "defense"
            : /проекци|проекция|projection/u.test(normalized)
              ? "projection"
              : /эмпати|эмпатия|empathy/u.test(normalized)
                ? "empathy"
                : /темперамент|temperament/u.test(normalized)
                  ? "temperament"
                  : /психологическ.{0,8}устойчив|психологиялык туруктуулук|psychological resilience/u.test(
                        normalized,
                      )
                    ? "resilience"
                    : null;
  return concept ? conceptReplies[concept][language] : replies.general_psychology[language];
}

export function expandedPsychologyReply(
  intent: string,
  language: GuidedLanguage,
  input = "",
) {
  if (intent === "general_psychology")
    return psychologyConceptReply(input, language);
  return replies[intent]?.[language];
}
